1	//! tower_vox.rs — the towers, written in IMASM, run on VOX, run on the GPU.
2	//!
3	//! The Factor Resonance Tower and the Dialetheic Resolution Tower are glyph
4	//! words.  Their values are glyph words too: N is a WordTape, and the tower
5	//! carries N's own word as its product mark.  Nothing in this module converts
6	//! a value to a limb vector or a BigUint to "do arithmetic"; the tower word is
7	//! the structure and the value word is the data, and vox::verdict is the one
8	//! reader that closes both — on the CPU auditor and on the device through
9	//! gpu_vox.
10	
11	use alloc::format;
12	use alloc::string::String;
13	use alloc::vec::Vec;
14	use num_bigint::BigUint;
15	
16	use crate::word_tape::WordTape;
17	
18	/// The Factor Resonance Tower, flat payload.  The dissolution rule has already
19	/// been applied: the two internal ∈...∋ dyads (candidate decomposition and
20	/// factor-pair self-test) collapsed into the one surviving outer dyad.
21	pub const FACTOR_TOWER_WORD: &str = "⊢⊙≻⋈∈⊤≻⋈⊙⊥≺⋈⊙⊙≻⋈⊙≺⋈⊙⊡⋈⊙∋⊣";
22	
23	/// The Dialetheic Resolution Tower, flat payload.  Here contradiction itself is
24	/// the matter being nested: truth evidence (⊤≻⋈⊙) and false evidence (⊥≺⋈⊙)
25	/// share one ambient mark and one surviving dyad.
26	pub const DIALETHIC_TOWER_WORD: &str = "⊢⊙∈⊤≻⋈⊙⊥≺⋈⊙∋⊡⊣";
27	
28	/// Encode N as its own IMASM word — the value is the glyph word, no limbs.
29	pub fn encode_value(n: &BigUint) -> String {
30	    WordTape::from_biguint(n).0.clone()
31	}
32	
33	/// Splice `value` in place of the first ⊙ that lies INSIDE the tower's own
34	/// fork/fuse span (after the first ∈), not merely the first ⊙ in the raw
35	/// text. `vox pairs` on the flat payloads shows the textually-first ⊙ sits
36	/// BEFORE the tower's ∈ ever opens — splicing there leaves N's own dyads
37	/// (one ∈/∋ pair per bit, from `encode_value`) as regions wholly outside the
38	/// tower's real work span, with no ancestry relationship to it at all: 8
39	/// disjoint closed regions instead of N genuinely nested inside the one
40	/// region that does the work. vox::verdict still reads T either way, since T
41	/// only certifies that everything opened is closed, not that N ever entered
42	/// the span — so the carrying was silently inert. Splicing at the first
43	/// interior ⊙ instead nests N's whole word inside the tower's fork/fuse
44	/// span, confirmed by `vox pairs`: the outer region's own span and interior
45	/// text now contain N's cells rather than sitting ahead of them.
46	fn carry_at_interior_mark(tower: &str, value: &str) -> String {
47	    let fork = tower.find('∈').expect("tower payload has no fork");
48	    let interior_mark = tower[fork..]
49	        .find('⊙')
50	        .map(|off| fork + off)
51	        .expect("tower payload has no ⊙ inside its fork/fuse span");
52	    let mark_len = '⊙'.len_utf8();
53	    let mut out = String::with_capacity(tower.len() + value.len());
54	    out.push_str(&tower[..interior_mark]);
55	    out.push_str(value);
56	    out.push_str(&tower[interior_mark + mark_len..]);
57	    out
58	}
59	
60	/// The Factor Resonance Tower carrying N: splice N's word in place of the
61	/// product mark that sits inside the tower's own fork/fuse span. The tower
62	/// word is the structure; N's word is the value; nothing else is converted.
63	pub fn factor_tower_carrying(n: &BigUint) -> String {
64	    let value = encode_value(n);
65	    carry_at_interior_mark(FACTOR_TOWER_WORD, &value)
66	}
67	
