    unsigned long long r = 0ULL; a %= m;
    while (b) { if (b & 1ULL) { r += a; if (r >= m) r -= m; } a += a; if (a >= m) a -= m; b >>= 1ULL; }
    return r;
}
extern "C" __global__ void run_factor_ml(
    const unsigned long long* limbs, unsigned int n_limbs,
    unsigned long long* out, unsigned int k, unsigned int tpn,
    unsigned long long dstart, unsigned long long dend)
{
    unsigned long long gid = (unsigned long long)blockIdx.x * blockDim.x + threadIdx.x;
    unsigned long long total = (unsigned long long)k * tpn;
    if (gid >= total) return;
    unsigned int lane = (unsigned int)(gid / tpn);
    unsigned int t    = (unsigned int)(gid % tpn);
    const unsigned long long* N = limbs + (unsigned long long)lane * n_limbs;

