    // to sqrt(N), so there is no ceiling on the total sweep; each launch is one
    // bounded window that returns. N mod d is a Horner fold over the limbs from
    // the top: r = r*(2^64) + limb, each step reduced mod d. 2^64 mod d is
    // (2^63 mod d) doubled mod d; the r*(2^64 mod d) product uses the mulmod
    // above, so d may run all the way to 2^63 with no small ceiling.
    unsigned long long d = dstart + 2ULL * (unsigned long long)t;
    unsigned long long step = 2ULL * (unsigned long long)tpn;
    for (; d < dend; d += step) {
        unsigned long long two64 = ( (1ULL << 63) % d );
        two64 += two64; if (two64 >= d) two64 -= d;   // = 2^64 mod d
        unsigned long long r = 0ULL;
